export function linearFit(points){if(points.length<3)return null;const n=points.length,mx=points.reduce((a,p)=>a+p[0],0)/n,my=points.reduce((a,p)=>a+p[1],0)/n,sxx=points.reduce((a,p)=>a+(p[0]-mx)**2,0);if(sxx<1e-15)return null;const slope=points.reduce((a,p)=>a+(p[0]-mx)*(p[1]-my),0)/sxx,intercept=my-slope*mx,ss=points.reduce((a,p)=>a+(p[1]-my)**2,0),err=points.reduce((a,p)=>a+(p[1]-(slope*p[0]+intercept))**2,0);return {slope,intercept,r2:ss<1e-15?1:Math.max(0,1-err/ss)};}
export function tableGraph(e,rows,x=0,y=1,fit=false){const pointRows=[],points=[];rows.forEach((r,i)=>{const p=[r.values[x],r.values[y]];if(p.every(v=>typeof v==='number'&&Number.isFinite(v))){points.push(p);pointRows.push(i);}});const xmin=Math.min(0,...points.map(p=>p[0]));let xmax=Math.max(0,...points.map(p=>p[0])),min=Math.min(0,...points.map(p=>p[1])),max=Math.max(0,...points.map(p=>p[1]));if(xmax-xmin<1e-15)xmax=xmin+1;if(max-min<1e-15){max+=1;min-=1;}const padding=(max-min)*.12,kind=fit===true?'linear':fit,regression=fit?fitModel(points,kind):null;return {points,pointRows,current:[],series:regression?[{label:'Khớp '+fitModels.find(m=>m.key===kind).label.toLowerCase(),color:'#527948',data:regression.curve}]:[],xmin,xmax,ymin:min-padding,ymax:max+padding,xLabel:e.headers[x],yLabel:e.headers[y],regression};}
export function sweepStates(e,state,key,start,end,count){const p=e.params.find(p=>p.key===key);if(!p||!Number.isFinite(start)||!Number.isFinite(end)||start<p.min||end>p.max||end<start||!Number.isInteger(count)||count<2||count>25)throw Error('Khoảng quét không hợp lệ.');return Array.from({length:count},(_,i)=>({...state,[key]:+(start+(end-start)*i/(count-1)).toFixed(6)}));}
export function segments(data){const parts=[];let part=[];for(const p of data){if(p.every(Number.isFinite)){part.push(p);}else if(part.length){parts.push(part);part=[];}}if(part.length)parts.push(part);return parts;}
export function graphParameter(e,c={}){if(e.graph)return e.graph.key;const mapping={ohm:'u',series:'u',parallel:'u',wave:'f',boyle:'v',gas:c.gasAxis==='v'?'v':'tK',newton:'force',incline:'angle',lever:'l2',pendulum:'length',resonance:'f',interference:'probeX',standing:'probeX',magnetic:'angle'};if(['electric','hooke','horizontal','projectile'].includes(e.id))return null;return mapping[e.id]||'t';}
